import type { ExitLot } from "./exit-planner";

export const EXIT_PRICE_WAIT_MAX_SECS = 60 * 60;

export function reconcileLotsToChainQty(lots: ExitLot[], chainQty: number, nowSecs: number): ExitLot[] {
    const sum = lots.reduce((s, l) => s + l.qty, 0);
    if (Math.abs(sum - chainQty) < 1e-12)
        return lots;
    const sorted = [...lots].sort((a, b) => b.basisPerUnitUsd - a.basisPerUnitUsd);
    if (sum > chainQty) {
        const out: ExitLot[] = [];
        let left = chainQty;
        for (const l of sorted) {
            if (left <= 1e-12)
                break;
            const take = Math.min(l.qty, left);
            out.push({ ...l, qty: take });
            left -= take;
        }
        return out;
    }
    return [...lots, { lotId: `chain-remainder`, qty: chainQty - sum, basisPerUnitUsd: 0, acquiredAt: nowSecs }];
}

export function decideUsdcResidual(args: {
    residualUsdcQty: number;
    dustThreshold: number;
    hasConfirmedPriorSweep: boolean;
    hasDestination: boolean;
}): "close" | "sweep" | "residual_after_sweep" | "no_destination" {
    if (args.residualUsdcQty < args.dustThreshold)
        return "close";
    if (args.hasConfirmedPriorSweep)
        return "residual_after_sweep";
    return args.hasDestination ? "sweep" : "no_destination";
}
